  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law allows cities to set the number of homes permitted on residential lots. The measure overrides local limits, requiring all cities to allow up to two homes on any single-family zoned lot and prohibiting cities from requiring public hearings to approve these projects.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Property owners benefit by gaining the right to build an additional home on their lot. Builders and developers benefit from a streamlined approval process. Neighbors who wish to oppose nearby development lose the venue of a public hearing to contest projects.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Property owners may increasingly build duplexes or second units on single-family lots. Cities will update their approval processes to process these applications ministerially without holding public hearings.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses housing shortages and the barrier of local zoning restrictions. By legalizing two homes on single-family lots and removing discretionary public hearings, it removes entry barriers and regulatory delays that restrict housing supply.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Property owners gain discretion over their land use. State lawmakers exert power over local land use. Local governments, city councils, and neighborhood organizations lose the power to block or delay these specific housing projects through discretionary review.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "Researchers disagree on the extent to which upzoning single-family lots produces significant new housing; some find it leads to moderate, steady increases in housing supply, while others find that high construction costs and financing barriers limit actual new development despite the zoning changes.",
      "disputed": true
    }
  ],
